          "<h4>Francisca 'Pancha' Carrasco — Heroína Nacional</h4>",
          "<p><strong>Francisca 'Pancha' Carrasco</strong> fue la figura femenina más destacada de la Campaña Nacional. Mientras los hombres luchaban en el ejército, las mujeres costarricenses asumieron el control del país: se encargaron de los cultivos y el ganado, mantuvieron la educación y se ocuparon de la crianza de los niños. Pancha Carrasco ya había participado durante la batalla de <strong>Francisco Morazán en 1842</strong> y volvió a participar activamente en 1856.</p>",
          "<p>En el campo de batalla acompañó al ejército cumpliendo labores esenciales: cuidar a los soldados heridos, cocinar, enterrar a los muertos, y — de manera muy destacada — <strong>recuperar un cañón que los filibusteros habían tomado durante la Batalla de Rivas</strong>. Por su valentía y contribución, hizo un llamado a las demás mujeres para que participaran activamente en la defensa de la patria. La <strong>Asamblea Legislativa la declaró Heroína Nacional en 1994</strong>.</p>",
          "<p>Los <strong>pueblos indígenas</strong> de Costa Rica también participaron activamente en la Campaña Nacional, apoyando al ejército costarricense en su lucha contra los filibusteros. La Campaña fue, en suma, un esfuerzo de todo el pueblo costarricense: hombres, mujeres, niños y pueblos indígenas.</p>",
          "<h4>El concepto de héroe en el presente</h4>",
          "<p>El concepto de héroe se extiende hacia el presente: los héroes actuales son todas las personas que trabajan diariamente por mejorar el país, ayudan a quienes lo necesitan o enaltecen el nombre de Costa Rica en diferentes disciplinas — bomberos, médicos, deportistas, docentes, artistas, entre otros.</p>",
          "<h4>Filibusteros del pasado y del presente</h4>",
          "<p>Los <strong>filibusteros del pasado</strong> (Walker y sus hombres) deseaban adueñarse de tierras ajenas y esclavizar a sus habitantes. Fueron vencidos gracias a la unión del pueblo costarricense, la valentía de los soldados y el liderazgo del presidente Mora. Los <strong>filibusteros del presente</strong> son, de manera simbólica, todas aquellas personas que actúan en contra de los intereses de la nación o que buscan apropiarse de lo que no les pertenece — por ejemplo, quienes cometen actos de corrupción, tráfico ilegal o perjudican el bien común."
