          "<p>Los Estudios Sociales son una materia muy importante porque nos ayuda a entender cómo funciona el mundo en el que vivimos. Gracias a esta materia, aprendemos sobre la historia de nuestro país, cómo se organizan las personas en sociedad, y por qué es importante ser un buen ciudadano. También nos enseña a respetar a los demás, conocer nuestros derechos y cumplir con nuestros deberes como costarricenses.</p>",
          "<p>La Educación Cívica va de la mano con los Estudios Sociales porque nos enseña cómo participar de manera responsable en nuestra comunidad y en nuestro país. Incluye valores como el respeto, la democracia y la responsabilidad.</p>",
          "<h3>📌 Puntos importantes a recordar</h3>",
          "<ul>",
          "<li>Los Estudios Sociales estudian el desarrollo de la humanidad a través del tiempo y su relación con el espacio.</li>",
          "<li>Nos ayudan a comprender la sociedad del pasado, el presente y el futuro.</li>",
          "<li>Sus objetivos son: darnos una visión general de la sociedad, desarrollar destrezas, identificarnos con nuestra patria y reconocer los valores de la democracia.</li>",
          "<li>La Educación Cívica fomenta el respeto por los valores y símbolos nacionales.</li>",
          "<li>Prepara ciudadanos responsables, capaces y autosuficientes.</li>",
          "<li>Promueve la participación en un gobierno democrático.</li>",
          "</ul>",
