          "<p>Cuando Costa Rica se independizó de España, necesitaba reglas para organizarse como país. Por eso, el 1° de diciembre de 1821, una Junta de Legados redactó el Pacto de Concordia. Este documento fue la primera Constitución Política de Costa Rica y sentó las bases de cómo debía funcionar nuestro país. Aunque solo estuvo vigente dos años, su importancia llega hasta nuestros días porque estableció que Costa Rica sería un país libre, ordenado y respetuoso de sus ciudadanos.</p>",
