          "<li><strong>1823</strong>: Deja de tener vigencia.</li>",
          "<li>También se llama <strong>Pacto Social Fundamental Interino de Costa Rica</strong>.</li>",
          "<li>Fue la <strong>primera Constitución Política</strong> de Costa Rica.</li>",
