          "<p>Costa Rica no es un país de una sola cultura o de un solo tipo de personas. Somos un país diverso, donde conviven personas de diferentes etnias, idiomas y tradiciones. La Constitución dice que Costa Rica es una <strong>República democrática, libre, independiente, multiétnica y pluricultural</strong>.</p>",
