          "<p> <strong>Multiétnica</strong>  -  La sociedad está conformada por diversas etnias: indígenas, mestizos, mulatos, asiáticos y afrodescendientes </p>",
          "<p> <strong>Plurilingüe</strong>  -  En Costa Rica se comparten diversas lenguas que se integran para conformar la cultura nacional </p>",
